// Fallo no controlado en un workflow de ofertas → Slack + Command Center (cola de atención)
return $input.all().map(({ json: e }) => {
const wfName = e.workflow?.name || '';
const SLUGS = [
  [/bankinter/i,'bankinter'],[/caixabank/i,'caixabank'],[/caixapopular/i,'caixa_popular'],[/cr ?arag/i,'cr_aragon'],
  [/cr ?asturias/i,'cr_asturias'],[/cr ?granada/i,'cr_granada'],[/cr ?sur/i,'cr_del_sur'],[/cr ?teruel/i,'cr_teruel'],
  [/deutsche/i,'deutsche_bank'],[/eurocaja/i,'eurocajarural'],[/globalcaja/i,'globalcaja'],[/^ing[_ ]/i,'ing'],
  [/ibercaja/i,'ibercaja'],[/laboral/i,'laboral_kutxa'],[/myinvestor/i,'myinvestor'],[/sabadell/i,'sabadell'],
  [/uci/i,'uci'],[/unicaja/i,'unicaja'],[/santander/i,'santander'],[/kutxabank/i,'kutxabank'],
];
const slug = (SLUGS.find(([re]) => re.test(wfName)) || [])[1] || null;
const execId = e.execution?.id || null;
const url = e.execution?.url || (execId ? `https://huspy.app.n8n.cloud/workflow/${e.workflow?.id}/executions/${execId}` : '');
const msg = String(e.execution?.error?.message || e.trigger?.error?.message || 'Error desconocido').slice(0, 900);
const node = e.execution?.lastNodeExecuted || e.execution?.error?.node?.name || '—';
return { json: {
  slack: `🚨 *FALLO WORKFLOW OFERTAS* — ${wfName}\n📍 Nodo: \`${node}\`\n❌ ${msg}\n🔗 <${url}|Ver ejecución>`,
  registro: slug && execId ? {
    bank_slug: slug, source: 'manual', external_id: `n8n-error-${execId}`,
    subject: `Fallo en ${wfName}`, match_status: 'unmatched', classification: 'other', status: 'error',
    error_step: node, error_message: msg, workflow_id: e.workflow?.id, execution_id: execId,
    summary: 'Ejecución fallida sin manejo de error: revisar el correo del banco y procesarlo a mano',
  } : null,
} };
});

// Vigilancia de fallos en los workflows de bancos.
// Desde que el Repartidor los lanza como subflujos (modo "integrated"), n8n NO dispara el Error Trigger
// cuando fallan. Este paso consulta cada 10 min las ejecuciones con error y las envía al mismo flujo de aviso.
const BANKS = {"YqQIDjAozwsDAQR1": "CRSur_Offers_Received", "d3S1y48F0qKoVc6O": "Bankinter_Offers_Received_v19", "IOIg26EPCqtgCSLv": "CRAragón_Offers_Received", "12m8gBooQnUpwG14": "CRAsturias_Offers_Received", "Yd82lkDzorla4x7T": "CRGranada_Offers_Received", "eoxXdCBbq6zFL2me": "CRTeruel_Offers_Received_v3", "RezivFIqH10FdaB9": "CaixaBank_Offers_Received", "O6V1P2efIYpyu1bC": "CaixaPopular_Offers_Received_v2", "sEQ8HDbHIB3HvPDY": "DeutscheBank_Offers_Received", "qXIKYBEK2Yr7LWWs": "EuroCajaRural_Offers_Received", "n35da7vAodC9XUsH": "Globalcaja_Offers_Received", "IZpYM4yNvwza5ol7": "ING_Offers_Received", "VI1n8UQng6gAWV8B": "Ibercaja_Offers_Received", "iMzC4NjXDOlCbPuf": "LaboralKutxa_Offers_Received", "mxewpxzScRz3jHX2": "MyInvestor_Offers_Received_v2", "ZtErLRcQa0SwXfZb": "Sabadell_Offers_Received_v1", "pNOk4VBlVu9PLdKV": "UCI_Offers_Received", "hY2DR1im7zSNx28E": "Unicaja_Offers_Received_v4"};
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const first = !sd.seen;
sd.seen = sd.seen || {};
const out = [];
for (const e of ($input.first().json.data || [])) {
  if (!BANKS[e.workflowId] || sd.seen[e.id]) continue;
  sd.seen[e.id] = now;
  if (first) continue;   // primera ejecución: solo memoriza los fallos existentes, no avisa de errores antiguos
  const rd = e.data?.resultData || {};
  out.push({ json: {
    workflow: { id: e.workflowId, name: BANKS[e.workflowId] },
    execution: { id: e.id, url: `https://huspy.app.n8n.cloud/workflow/${e.workflowId}/executions/${e.id}`,
                 lastNodeExecuted: rd.lastNodeExecuted || rd.error?.node?.name || null,
                 error: { message: rd.error?.message || rd.error?.description || 'Error desconocido' } },
  } });
}
for (const [id, t] of Object.entries(sd.seen)) if (now - t > 3 * 24 * 3600e3) delete sd.seen[id];   // limpia memoria > 3 días
return out;
